    manifest=[]
    def record(path,location,relative):
        data=path.read_bytes();manifest.append(dict(location=location,path=relative,bytes=len(data),sha256=SHA(data)))
    for path in sorted(output.rglob('*')):
        if path.is_file() and path.name!='source-manifest.json':record(path,'output',path.relative_to(output).as_posix())
    repository_files={producer,*helpers,*refs,*[repo/r['path'] for files in dependencies.values() for r in files.values()]}
    for path in sorted(repository_files):record(path,'repository',path.relative_to(repo).as_posix())
    for path in sorted(originals):record(path,'local-original',path.relative_to(study).as_posix())
    assert len(manifest)==len({(r['location'],r['path']) for r in manifest})
    doc=dict(schema='gothic3-game-argv-source-manifest-v1',inputs={'Game':GAME},manifestSelfReferenceExcluded=True,
        producerPath=producer.relative_to(repo).as_posix(),helperPaths=[p.relative_to(repo).as_posix() for p in helpers],
        logicalOutputPath=LOGICAL,files=sorted(manifest,key=lambda r:(r['location'],r['path'])),**FLAGS)
    (output/'source-manifest.json').write_text(json.dumps(doc,separators=(',',':'))+'\n',encoding='utf8',newline='\n')
    assert len([p for p in output.rglob('*') if p.is_file()])==22
    print(json.dumps(dict(counts,outputFiles=22,manifestRecords=len(manifest),producerSha256=SHA(producer.read_bytes()))))


